#!/usr/bin/env python3
"""Approximate transitive #include reachability over a git tree.

Parses every header in the tree (over-approximating by ignoring #ifdef
conditions) and answers whether a target header is reachable from a source.
This is a static, network-free helper for include-closure questions when no
compiler is available.
"""
import re
import subprocess
import sys

INCLUDE_RE = re.compile(r'^\s*#\s*include\s*[<"]([^>"]+)[>"]')


def main():
    repo, commit, start, target = sys.argv[1:5]
    listing = subprocess.check_output(
        ["git", "-C", repo, "ls-tree", "-r", "--name-only", commit], text=True
    )
    files = set(listing.split())
    cache = {}

    def get(path):
        if path not in cache:
            try:
                cache[path] = subprocess.check_output(
                    ["git", "-C", repo, "show", f"{commit}:{path}"], text=True
                )
            except subprocess.CalledProcessError:
                cache[path] = None
        return cache[path]

    def resolve(inc):
        cands = [inc]
        if not inc.startswith("include/") and not inc.startswith("arch/"):
            cands.insert(0, "include/" + inc)
        for c in cands:
            if c in files:
                return c
        return None

    seen = set()
    stack = [start]
    parent = {start: None}
    while stack:
        path = stack.pop()
        data = get(path)
        if data is None:
            continue
        for line in data.splitlines():
            m = INCLUDE_RE.match(line)
            if not m:
                continue
            resolved = resolve(m.group(1))
            if resolved and resolved not in seen:
                seen.add(resolved)
                parent[resolved] = path
                stack.append(resolved)

    print(f"source={start} commit={commit}")
    print(f"target={target} reachable={'YES' if target in seen else 'NO'}")
    if target in seen:
        chain = []
        cur = target
        while cur is not None:
            chain.append(cur)
            cur = parent.get(cur)
        print("chain=" + " <- ".join(chain))
    print(f"reachable_headers={len(seen)}")


if __name__ == "__main__":
    main()

